"""Build the generated files of the SAM 2.1 pipeline from their sources.

Sources (edit these), each a folder with one file per notebook cell:

    cells/              the pipeline notebook
    demo_cells/         the short demo notebook
    count_test_cells/   the count test on the WGISD test photos

Generated (do not edit by hand), all under sam2_pipeline/:

    notebooks/MSU_FRUIT_SAM2_pipeline.ipynb   the full notebook
    fruit_sam2.py       the notebook's tool cells as one module, which fruit.py
                        and the HPCC jobs import
    demo.ipynb          the quick demo
    count_test.ipynb    detector → SAM 2.1 counts against hand counts on 27 photos

Run it from anywhere inside the repository:

    python sam2_pipeline/source/build.py
"""

import ast
import sys
from pathlib import Path

import nbformat as nbf

HERE = Path(__file__).resolve().parent
CELLS = HERE / "cells"
DEMO_CELLS = HERE / "demo_cells"
COUNT_CELLS = HERE / "count_test_cells"

# The repository to write into: this one, or the folder given on the command line.
REPO = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE.parent.parent
PIPE = REPO / "sam2_pipeline"

# Cells that hold definitions only. Together they are the module that fruit.py imports.
MODULE_CELLS = ["030", "040", "042", "044", "046", "048", "050", "052", "054"]

MODULE_HEADER = '''"""MSU FRUIT · SAM 2.1 pipeline as one importable module.

GENERATED by source/build.py from the notebook's tool cells, so the notebook and the
HPCC batch jobs run exactly the same code. Edit source/cells/, then rebuild; do not
edit this file by hand.

    import fruit_sam2 as F

    F.use_project("../data")
    F.finetune("grapes_v1", steps=3000)
    F.benchmark(F.load_lineup("configs/lineup.yaml"))

The project folder given to use_project() holds videos/, dataset/, predictions/,
models/ and results/. The command-line front end is fruit.py; the SLURM job scripts
in hpcc/ call it.
"""

# Defaults that the notebook's settings form (cell A) would set. There is no project
# folder until use_project() is called.
_DEFER_PROJECT = True
PROJECT_NAME = "msu_fruit_sam2"
DEMO = False
SAVE_TO_DRIVE = False
SAM2_SIZE = "base_plus"
OBJECT_NAME = "grape cluster"
PROJECT_DIR = ""
'''

RULE = "# " + "=" * 86


def notebook(cell_dir, path, colab_gpu=True):
    """Write one notebook: a cell per .py or .md file of cell_dir, in file-name
    order.
    """
    cells = []
    for f in sorted(p for p in cell_dir.iterdir() if p.suffix in (".py", ".md")):
        text = f.read_text().rstrip() + "\n"
        # The cell ids are the file names, so a rebuild gives an identical file and
        # git shows only real changes.
        if f.suffix == ".md":
            cells.append(nbf.v4.new_markdown_cell(text.rstrip(), id=f.stem))
            continue
        # A syntax error in a cell fails the build.
        ast.parse(text, filename=f.name)
        cell = nbf.v4.new_code_cell(text.rstrip(), id=f.stem)
        if text.startswith(("# @title", "#@title")):
            # Colab: show the title and the form, fold the code.
            cell.metadata["cellView"] = "form"
        cell.metadata["source_file"] = f.name
        cells.append(cell)
    meta = {
        "kernelspec": {
            "display_name": "Python 3",
            "language": "python",
            "name": "python3",
        },
        "language_info": {"name": "python"},
    }
    if colab_gpu:
        meta["accelerator"] = "GPU"
        meta["colab"] = {"provenance": [], "gpuType": "T4", "toc_visible": True}
    nb = nbf.v4.new_notebook(cells=cells, metadata=meta)
    nbf.validate(nb)
    path.parent.mkdir(parents=True, exist_ok=True)
    nbf.write(nb, path)
    print(f"{path.relative_to(REPO)}  ·  {len(cells)} cells")


def module(path):
    """Write the module: the header, then the cells named in MODULE_CELLS."""
    parts = [MODULE_HEADER]
    for prefix in MODULE_CELLS:
        f = next(CELLS.glob(prefix + "_*.py"))
        banner = f"{RULE}\n# from source/cells/{f.name}\n{RULE}"
        parts.append(f"\n\n{banner}\n{f.read_text().rstrip()}\n")
    code = "".join(parts)
    ast.parse(code, filename=path.name)
    path.write_text(code)
    print(f"{path.relative_to(REPO)}  ·  {len(code.splitlines())} lines")


if __name__ == "__main__":
    notebook(CELLS, PIPE / "notebooks" / "MSU_FRUIT_SAM2_pipeline.ipynb")
    notebook(DEMO_CELLS, PIPE / "demo.ipynb", colab_gpu=False)
    notebook(COUNT_CELLS, PIPE / "count_test.ipynb", colab_gpu=False)
    module(PIPE / "fruit_sam2.py")
